"use client";

import { clamp01, mixOklch, useFramecnTheme } from "@/lib/framecn-ui";
import type { FramecnTheme } from "@/lib/framecn-ui";

export interface ProgressStyle {
  value: number;
}

export interface ProgressProps {
  value?: number;
  style?: ProgressStyle;
  width?: number;
  showLabel?: boolean;
  theme?: Partial<FramecnTheme>;
  className?: string;
}

const TRACK_HEIGHT = 8;

const clampValue = (value: number): number => clamp01(value / 100) * 100;

export const Progress = ({
  value = 0,
  style,
  width = 320,
  showLabel = false,
  theme: themeOverride,
  className,
}: ProgressProps) => {
  const theme = useFramecnTheme(themeOverride);
  const v = clampValue(style ? style.value : value);
  const track = mixOklch(theme.primary, "transparent", 0.8);
  const indicator = theme.primary;
  return (
    <div
      className={className}
      style={{
        alignItems: "center",
        display: "inline-flex",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        gap: 12,
      }}
    >
      <div
        style={{
          background: track,
          borderRadius: TRACK_HEIGHT / 2,
          height: TRACK_HEIGHT,
          overflow: "hidden",
          position: "relative",
          width,
        }}
      >
        <div
          style={{
            background: indicator,
            borderRadius: TRACK_HEIGHT / 2,
            bottom: 0,
            left: 0,
            position: "absolute",
            top: 0,
            width: `${v}%`,
          }}
        />
      </div>
      {showLabel && (
        <span
          style={{
            color: theme.mutedForeground,
            fontSize: 14,
            fontVariantNumeric: "tabular-nums",
            fontWeight: 500,
            minWidth: "3ch",
            textAlign: "right",
          }}
        >
          {Math.floor(v)}%
        </span>
      )}
    </div>
  );
};

"use client";

import { clamp01, easings, useCurrentFrame } from "@/lib/framecn-ui";
import type { EasingName } from "@/lib/framecn-ui";
import type { ProgressStyle } from "@/components/framecn/progress";

export interface ProgressStep {
  at: number;
  value: number;
  duration?: number;
  easing?: EasingName;
}

export const DEFAULT_DURATION = 24;

export interface ProgressTransitionOptions {
  speed?: number;
  defaultDuration?: number;
}

export const tweenProgressStyle = (
  a: ProgressStyle,
  b: ProgressStyle,
  t: number
): ProgressStyle => ({ value: a.value + (b.value - a.value) * t });

export const progressValueAt = (
  steps: ProgressStep[],
  raw: number,
  opts: ProgressTransitionOptions = {}
): ProgressStyle => {
  const { defaultDuration = DEFAULT_DURATION } = opts;
  if (steps.length === 0) {
    return { value: 0 };
  }
  const [first] = steps;
  if (raw <= first.at) {
    return { value: first.value };
  }
  let toIndex = steps.length - 1;
  for (let i = 1; i < steps.length; i += 1) {
    if (steps[i].at > raw) {
      toIndex = i;
      break;
    }
  }
  const last = steps.at(-1);
  if (!last) {
    return { value: 0 };
  }
  const pastLast = raw >= last.at;
  const to = pastLast ? last : steps[toIndex];
  const from = pastLast ? last : steps[toIndex - 1];
  if (to === undefined || from === undefined) {
    return { value: first.value };
  }
  const dur = to.duration ?? defaultDuration;
  const ease = easings[to.easing ?? "out"];
  const start = to.at - dur;
  const t = pastLast || dur <= 0 ? 1 : ease(clamp01((raw - start) / dur));
  const value = from.value + (to.value - from.value) * t;
  return { value };
};

export const useProgressTransition = (
  steps: ProgressStep[],
  opts: ProgressTransitionOptions = {}
): ProgressStyle => {
  const { speed = 1 } = opts;
  const raw = useCurrentFrame() * speed;
  return progressValueAt(steps, raw, opts);
};
